#!/usr/bin/env bash
# argo-cd/argo-workflows 1.0.14 - base variant: controller-default-reviewed
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/argo-cd-argo-workflows-1-0-14.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the controller-default-reviewed base variant into ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/argo-cd-argo-workflows:1.0.14 --base controller-default-reviewed --work-dir ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

if [ "${REQUIREMENTS_READY:-0}" != "1" ]; then
  cat >&2 <<'EOF_REQUIREMENTS'
This base variant needs resources you must create with your own values first:
  - CRD clusterworkflowtemplates.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD cronworkflows.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workflowartifactgctasks.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workfloweventbindings.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workflows.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workflowtaskresults.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workflowtasksets.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
  - CRD workflowtemplates.argoproj.io
    kubectl apply -f <crd-manifest.yaml>
Substitute the <...> placeholders and create these, then re-run with:
  REQUIREMENTS_READY=1 bash try.sh
EOF_REQUIREMENTS
  exit 1
fi

if [ -d ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed/out/manifests

say "Done. The cluster received exactly the files in ./argo-cd-argo-workflows-1-0-14-controller-default-reviewed/out."
